    fn environment_override_watches_parses() {
        let yaml = r#"
            watches: []
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.watches, Some(vec![]));
    }

    #[test]
    fn environment_override_title_parses() {
        let yaml = r#"
            title: "CI Title"
        "#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.title, Some("CI Title".to_string()));
    }

    // --- Vars parsing tests ---

    #[test]
    fn parses_static_var() {
        let yaml = r#"
vars:
  name: "bivvy"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("name"),
            Some(VarDefinition::Static(v)) if v == "bivvy"
        ));
    }

    #[test]
    fn parses_computed_var() {
        let yaml = r#"
vars:
  v:
    command: "echo 1"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(matches!(
            config.vars.get("v"),
            Some(VarDefinition::Computed { command }) if command == "echo 1"
        ));
    }

    #[test]
    fn parses_mixed_vars() {
        let yaml = r#"
vars:
  app_name: "bivvy"
  version:
    command: "echo 1.0.0"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.vars.len(), 2);
        assert!(matches!(
            config.vars.get("app_name"),
            Some(VarDefinition::Static(_))
        ));
        assert!(matches!(
            config.vars.get("version"),
            Some(VarDefinition::Computed { .. })
        ));
    }

    #[test]
    fn empty_vars_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert!(config.vars.is_empty());
    }

    #[test]
    fn serialize_omits_empty_vars() {
        let config: BivvyConfig = serde_yaml::from_str("app_name: test").unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(!yaml.contains("vars"), "empty vars should be omitted");
    }

    // --- Precondition parsing tests ---

    #[test]
    fn parses_precondition_command_succeeds() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: command_succeeds
      command: "test $(git branch --show-current) = main"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        assert!(matches!(
            step.precondition,
            Some(CompletedCheck::CommandSucceeds { .. })
        ));
    }

    #[test]
    fn parses_precondition_all() {
        let yaml = r#"
steps:
  release:
    command: "git tag v1"
    precondition:
      type: all
      checks:
        - type: command_succeeds
          command: "test $(git branch --show-current) = main"
        - type: command_succeeds
          command: "git diff --quiet"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["release"];
        if let Some(CompletedCheck::All { checks }) = &step.precondition {
            assert_eq!(checks.len(), 2);
        } else {
            panic!("Expected All precondition");
        }
    }

    #[test]
    fn precondition_defaults_none() {
        let yaml = r#"
            command: "echo hello"
        "#;
        let config: StepConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.precondition.is_none());
    }

    #[test]
    fn serialize_omits_none_precondition() {
        let config: BivvyConfig = serde_yaml::from_str(
            r#"
steps:
  hello:
    command: "echo hello"
"#,
        )
        .unwrap();
        let yaml = serde_yaml::to_string(&config).unwrap();
        assert!(
            !yaml.contains("precondition"),
            "None precondition should be omitted"
        );
    }

    #[test]
    fn environment_override_bare_null_parses_as_none() {
        let yaml = "command:";
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert!(o.command.is_none());
    }

    #[test]
    fn environment_override_empty_string_is_not_null() {
        let yaml = r#"command: """#;
        let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(o.command, Some("".to_string()));
    }

    // --- Unknown field rejection tests ---

    #[test]
    fn unknown_top_level_field_rejected() {
        let yaml = r#"
app_name: "MyApp"
unknown_field: "should fail"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown top-level field should be rejected");
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("unknown field"),
            "error should mention 'unknown field', got: {}",
            err
        );
    }

    #[test]
    fn typo_in_top_level_field_rejected() {
        let yaml = r#"
app-name: "MyApp"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "typo in top-level field should be rejected");
    }

    #[test]
    fn unknown_settings_field_rejected() {
        let yaml = r#"
settings:
  default_output: verbose
  loggging: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown settings field should be rejected");
    }

    #[test]
    fn unknown_step_field_rejected() {
        let yaml = r#"
steps:
  test:
    command: "echo test"
    commnad: "typo"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown step field should be rejected");
    }

    #[test]
    fn unknown_workflow_field_rejected() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    descritpion: "typo"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_err(), "unknown workflow field should be rejected");
    }

    #[test]
    fn unknown_workflow_settings_field_rejected() {
        let yaml = r#"
workflows:
  ci:
    steps: [test]
    settings:
      non_interctive: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown workflow settings field should be rejected"
        );
    }

    #[test]
    fn unknown_step_override_field_rejected() {
        let yaml = r#"
workflows:
  default:
    steps: [test]
    overrides:
      test:
        skip_prompts: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step override field should be rejected"
        );
    }

    #[test]
    fn unknown_environment_config_field_rejected() {
        let yaml = r#"
settings:
  environments:
    ci:
      detects:
        - env: CI
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown environment config field should be rejected"
        );
    }

    #[test]
    fn unknown_step_environment_override_field_rejected() {
        let yaml = r#"
steps:
  test:
    command: "echo test"
    environments:
      ci:
        commnad: "echo ci"
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(
            result.is_err(),
            "unknown step environment override field should be rejected"
        );
    }

    #[test]
    fn valid_config_still_parses() {
        let yaml = r#"
app_name: "MyApp"
settings:
  default_output: quiet
  logging: true
steps:
  test:
    command: "echo test"
    depends_on: [other]
workflows:
  default:
    steps: [test]
    overrides:
      test:
        skip_prompt: true
"#;
        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
        assert!(result.is_ok(), "valid config should parse: {:?}", result.err());
    }
}

